import jax.numpy as jnp
import flax.linen as nn
from jax import random
import optax
from typing import Dict, Any

class ResidualBlock(nn.Module):
    features: int
    kernel_size: int

    @nn.compact
    def __call__(self, x):
        residual = x
        y = nn.Conv(features=self.features, kernel_size=(self.kernel_size,), padding='SAME')(x)
        y = nn.relu(y)
        y = nn.Conv(features=self.features, kernel_size=(self.kernel_size,), padding='SAME')(y)

        if residual.shape[-1] != self.features:
            residual = nn.Conv(features=self.features, kernel_size=(1,), name='projection')(residual)

        return nn.relu(residual + y)

class ResNetCNN(nn.Module):
    d_output: int
    task_type: str
    num_blocks: int = 4
    initial_filters: int = 64
    kernel_size: int = 11 # Changed from 7 to 11
    dropout_rate: float = 0.4

    @nn.compact
    def __call__(self, x, deterministic=True):
        x = nn.Conv(features=self.initial_filters, kernel_size=(self.kernel_size,), padding='SAME')(x)
        x = nn.relu(x)

        current_filters = self.initial_filters
        for i in range(self.num_blocks):
            if i > 0:
                current_filters *= 2
            x = ResidualBlock(features=current_filters, kernel_size=self.kernel_size)(x)

        x = jnp.mean(x, axis=1)
        x = nn.Dropout(rate=self.dropout_rate)(x, deterministic=deterministic)
        x = nn.Dense(features=self.d_output)(x)

        if self.task_type == "regression":
            return x.squeeze(-1)
        else:
            return x

class ResNetWrapper:
    def __init__(self, d_output: int, task_type: str, num_blocks: int, initial_filters: int, kernel_size: int, dropout_rate: float):
        self.network = ResNetCNN(d_output=d_output, task_type=task_type, num_blocks=num_blocks, initial_filters=initial_filters, kernel_size=kernel_size, dropout_rate=dropout_rate)

    def init(self, rng_key, dummy_input):
        variables = self.network.init(rng_key, dummy_input, deterministic=True)
        return variables['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
        rngs = {'dropout': rng_key} if not deterministic else None
        return self.network.apply({'params': params}, x, deterministic=deterministic, rngs=rngs)

def create_network(hparams: Dict[str, Any]):
    return ResNetWrapper(
        d_output=hparams.get("d_output"),
        task_type=hparams.get("task_type"),
        num_blocks=hparams.get("num_blocks"),
        initial_filters=hparams.get("initial_filters"),
        kernel_size=hparams.get("kernel_size"),
        dropout_rate=hparams.get("dropout_rate")
    )

def _define_hyperparameters():
    return {
        'learning_rate': 0.001,
        'num_blocks': 4,
        'initial_filters': 64,
        'kernel_size': 11, # Changed from 7 to 11
        'dropout_rate': 0.4
    }

def create_optimizer(learning_rate: float = 0.001):
    total_steps = 50000 
    warmup_steps = 500

    schedule = optax.warmup_cosine_decay_schedule(
        init_value=0.0,
        peak_value=learning_rate,
        warmup_steps=warmup_steps,
        decay_steps=total_steps,
        end_value=1e-5
    )

    return optax.adamw(learning_rate=schedule, weight_decay=0.01)
